const imageAssets={"hero-motion.webp":"data:image/webp;base64,","hero-community.webp":"data:image/webp;base64,","community-huddle.webp":"data:image/webp;base64,"};
document.querySelectorAll("img[data-site-image],img[src]").forEach(img=>{const src=img.getAttribute("src");const name=img.dataset.siteImage||src?.split(/[?#]/)[0].split("/").pop();if(name&&imageAssets[name])img.src=imageAssets[name]});
const toggle=document.querySelector('.menu-toggle');
const nav=document.querySelector('#main-nav');
function closeMenu({restoreFocus=false}={}){nav?.classList.remove('open');toggle?.setAttribute('aria-expanded','false');if(restoreFocus)toggle?.focus({preventScroll:true})}
toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));nav?.classList.toggle('open',open)});
nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>closeMenu()));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&nav?.classList.contains('open')){event.preventDefault();closeMenu({restoreFocus:true})}});
document.addEventListener('click',event=>{if(nav?.classList.contains('open')&&!nav.contains(event.target)&&!toggle?.contains(event.target))closeMenu()});
document.addEventListener('focusin',event=>{if(nav?.classList.contains('open')&&!nav.contains(event.target)&&!toggle?.contains(event.target))closeMenu()});
const navBreakpoint=window.matchMedia('(max-width: 1024px)');
navBreakpoint.addEventListener('change',event=>{const focusInNav=nav?.contains(document.activeElement);closeMenu();if(event.matches&&focusInNav)toggle?.focus({preventScroll:true})});
document.addEventListener('click',event=>{if(event.detail!==0||event.defaultPrevented||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;const a=event.target.closest?.('a[href^="#"]');if(!a)return;const hash=a.getAttribute('href');if(!hash||hash==='#')return;const target=document.getElementById(decodeURIComponent(hash.slice(1)));if(!target)return;if(!target.hasAttribute('tabindex'))target.setAttribute('tabindex','-1');requestAnimationFrame(()=>target.focus({preventScroll:true}))});
