let category='all';
function renderResources(){const grid=document.querySelector('#resource-grid');if(!grid)return;const query=document.querySelector('#resource-search').value.toLowerCase().trim();const isFiltered=category!=='all'||Boolean(query);grid.classList.toggle('resource-grid--filtered',isFiltered);const filtered=articles.filter(a=>(category==='all'||a.category===category)&&a.title.toLowerCase().includes(query));const displayed=!isFiltered?filtered.slice(0,3):filtered;grid.innerHTML=displayed.length?displayed.map(a=>`<article class="resource-card"><div class="resource-cover cover-${a.category}"><img src="${imageAssets[a.icon==='sun'||a.icon==='arrow'?'hero-motion.webp':a.icon==='head'||a.icon==='heart'?'hero-community.webp':'community-huddle.webp']}" alt="" width="700" height="430" loading="lazy"><svg aria-hidden="true" viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round">${paths[a.icon]}</svg></div><div class="resource-body"><small>${a.label}</small><h3>${a.title}</h3><a href="https://tampabaysportsmed.org/${a.slug}/" aria-label="Read ${a.title}">Read the article <span aria-hidden="true">↗</span></a></div></article>`).join(''):'<p class="empty-state">No articles match your search. Try another topic or keyword.</p>';document.querySelector('#resource-count').textContent=displayed.length?`Showing ${displayed.length} of ${filtered.length} ${filtered.length===1?'resource':'resources'}${!isFiltered?' · Choose a topic or search to explore the collection.':''}`:'No resources match your search. Try another topic or keyword.';}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});renderResources()}));
document.querySelector('#resource-search')?.addEventListener('input',renderResources);renderResources();
document.querySelector('.contact-form form')?.addEventListener('submit',event=>{event.preventDefault();const message=document.querySelector('.form-message');message.textContent='Preview complete. No details were sent or saved. This form shows the proposed inquiry experience.';message.focus()});
const audiences={professional:{text:'For physicians, athletic trainers, physical therapists, and allied healthcare teams: connect across disciplines and express interest in future professional education.',cta:'Express membership interest',link:'membership-contact.html'},coach:{text:'For coaches, educators, schools, and sports organizations: explore practical education in athlete safety, emergency planning, and safer participation.',cta:'Request education information',link:'education-contact.html'},family:{text:'For athletes and parents: explore practical educational articles about heat illness, concussion recognition, injury recovery, and safer sports participation.',cta:'Explore athlete resources',link:'#resources'},partner:{text:'For healthcare organizations, schools, sports organizations, and sponsors: help shape regional education and community collaboration.',cta:'Explore a partnership',link:'sponsorship-contact.html'}};
function chooseAudience(key){const data=audiences[key];if(!data)return;document.querySelectorAll('[data-audience]').forEach(b=>{const selected=b.dataset.audience===key;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))});const detail=document.querySelector('#audience-detail');if(detail)detail.innerHTML=`<p>${data.text}</p><a class="text-link" href="${data.link}">${data.cta} <span aria-hidden="true">↗</span></a>`;}
document.querySelectorAll('[data-audience]').forEach(b=>b.addEventListener('click',()=>chooseAudience(b.dataset.audience)));
document.querySelectorAll('[data-select-audience]').forEach(a=>a.addEventListener('click',()=>chooseAudience(a.dataset.selectAudience)));
const focusImages=[{src:'hero-community',alt:'Illustrative healthcare professionals collaborating with an adult athlete',label:'LEARNING ACROSS DISCIPLINES'},{src:'hero-motion',alt:'Illustrative athlete training while a coach observes at a community track',label:'KNOWLEDGE FOR SAFER PARTICIPATION'},{src:'community-huddle',alt:'Illustrative community athletes and coaches gathered on a soccer field',label:'CONNECTED THROUGH COMMUNITY'}];
document.querySelectorAll('[data-focus]').forEach(button=>button.addEventListener('click',()=>{const selected=Number(button.dataset.focus);document.querySelectorAll('[data-focus]').forEach(b=>{const active=b===button;b.setAttribute('aria-expanded',String(active));b.querySelector('b').textContent=active?'−':'+';b.closest('.focus-item').classList.toggle('active',active);document.querySelector('#'+b.getAttribute('aria-controls')).hidden=!active});const photo=focusImages[selected];const img=document.querySelector('#education-image');img.src=imageAssets[photo.src+'.webp'];img.alt=photo.alt;document.querySelector('#education-image-label').textContent=photo.label}));
